drop policy if exists "members_select"             on public.group_members;
drop policy if exists "members_delete"             on public.group_members;

drop policy if exists "messages_select_member" on public.messages;
drop policy if exists "messages_insert_member" on public.messages;
drop policy if exists "messages_select"        on public.messages;
drop policy if exists "messages_insert"        on public.messages;

drop policy if exists "requests_select_member"              on public.loan_requests;
drop policy if exists "requests_insert_member"              on public.loan_requests;
drop policy if exists "requests_update_borrower"            on public.loan_requests;
drop policy if exists "requests_update_borrower_restricted" on public.loan_requests;
drop policy if exists "requests_select"                     on public.loan_requests;
drop policy if exists "requests_insert"                     on public.loan_requests;
drop policy if exists "requests_update"                     on public.loan_requests;

drop policy if exists "interests_select_member" on public.loan_interests;
drop policy if exists "interests_insert_member" on public.loan_interests;
drop policy if exists "interests_delete_own"    on public.loan_interests;
drop policy if exists "interests_select"        on public.loan_interests;
drop policy if exists "interests_insert"        on public.loan_interests;
drop policy if exists "interests_delete"        on public.loan_interests;

-- Now safe to drop old functions (no live policies depend on them)
drop function if exists public.join_group_by_invite(text, text);
drop function if exists public.get_my_wallet();
drop function if exists public.consume_nonce(text, text);
drop function if exists public.update_loan_request_status(uuid, text, bigint);
drop function if exists public.update_loan_request_status(uuid, text);

-- Drop old functions from v3 that are being replaced (new signatures differ)
drop function if exists public._verified_wallet_for_uid(uuid);
drop function if exists public.is_member_of(uuid);
drop function if exists public.my_uid();
drop function if exists public.create_group(text, text);
drop function if exists public.join_group_by_invite(text);
drop function if exists public.upsert_my_profile(text);
drop function if exists public.update_loan_request_by_borrower(uuid, text, boolean, uuid);
drop function if exists public.update_loan_request_by_borrower(uuid, text, boolean, uuid, text);

-- Drop legacy nonces table (no CASCADE â€” fail loudly if something unexpectedly
-- depends on it, rather than silently cascading damage)
drop table if exists public.nonces;

-- â”€â”€ STEP 3: CREATE TABLEs (IF NOT EXISTS â€” idempotent on existing project) â”€â”€â”€â”€

create table if not exists public.profiles (
