’vÆÆWBFG&W7226VæFW"à ¢ÒÒ)H)HÆöå÷&WVW7G2)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H)H␀¦ÇFW"F&ÆRV&Æ–2æÆöå÷&W]tÓ[h‘éì¶»§q«^ur_id, wallet, display_name)
  values (v_uid, v_wallet, p_display_name)
  on conflict (user_id) do update
    set display_name = coalesce(excluded.display_name, public.profiles.display_name),
        wallet       = public.profiles.wallet   -- immutable after first insert
  returning * into v_profile;

  return v_profile;
end;
$$;

revoke all    on function public.upsert_my_profile(text) from public, anon;
grant  execute on function public.upsert_my_profile(text) to authenticated;

-- â”€â”€ create_group() â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
-- LB-023, LB-038, LB-039 FIX: atomic group + owner-membership creation.
-- No direct INSERT or UPDATE policy on groups. owner_id, owner, invite_code
-- are set server-side and cannot be changed by clients.
create or replace function public.create_group(
  p_name        text,
  p_description text default null
)
returns public.groups
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid    uuid;
  v_wallet text;
  v_group  public.groups;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'unauthenticated'
      using hint = 'You must be signed in to create a group.';
  end if;

  p_name := trim(p_name);
  if length(p_name) = 0 or length(p_name) > 80 then
    raise exception 'invalid_name'
      using hint = 'Group name must be 1â€“80 characters.';
  end if;

  -- LB-039 FIX: no fallback to profiles.wallet
  v_wallet := public._verified_wallet_for_uid(v_uid);
  if v_wallet is null then
    raise exception 'no_identity'
      using hint = 'Web3 identity not found. Please sign in again.';
  end if;

  if v_wallet !~ '^0x[0-9a-f]{40}$' then
    raise exception 'invalid_wallet'
      using hint = 'Wallet address from identity has an unexpected format.';
  end if;

  insert into public.groups (name, description, owner_id, owner)
  values (p_name, p_description, v_uid, v_wallet)
  returning * into v_group;

  insert into public.group_members (group_id, user_id, wallet, role)
  values (v_group.id, v_uid, v_wallet, 'owner');

  return v_group;
end;
$$;

revoke all    on function public.create_group(text, text) from public, anon;
grant  execute on function public.create_group(text, text) to authenticated;

-- â”€â”€ update_group_metadata() â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
-- LB-038 FIX: only owner may call this; only name and description are mutable.
-- owner_id, owner (wallet), and invite_code are permanently immutable after
-- group creation â€” no client path can change them.
create or replace function public.update_group_metadata(
  p_group_id    uuid,
  p_name        text  default null,
  p_description text  default null
)
returns public.groups
language plpgsql
security definer
set search_path = public
