revoke all    on function public.express_interest(uuid) from public, anon;
grant  execute on function public.express_interest(uuid) to authenticated;

-- â”€â”€ withdraw_interest() â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
-- Lender withdraws their own interest record. Mirrors the interests_delete_own
-- policy for callers who prefer an RPC path.
create or replace function public.withdraw_interest(
  p_request_id uuid
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'unauthenticated';
  end if;

  delete from public.loan_interests
   where request_id = p_request_id
     and lender_id  = v_uid;
end;
$$;

revoke all    on function public.withdraw_interest(uuid) from public, anon;
grant  execute on function public.withdraw_interest(uuid) to authenticated;

-- â”€â”€ update_loan_request_by_borrower() â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
-- Borrower mutations: update note, cancel, select lender.
-- Protected fields (amount, duration, group, borrower, onchain_loan_id) cannot
-- be changed through any client path.
-- The lender wallet is read from auth.identities (server-authoritative).
-- LB-039 FIX: lender wallet fallback to profiles.wallet removed.
create or replace function public.update_loan_request_by_borrower(
  p_request_id         uuid,
  p_note               text    default null,
  p_cancel             boolean default false,
  p_selected_lender_id uuid    default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid           uuid;
  v_current       record;
  v_lender_wallet text;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'unauthenticated';
  end if;

  -- Lock the row and verify ownership in one step
  select status, borrower_id, group_id
    into v_current
    from public.loan_requests
   where id = p_request_id
  for update;

  if not found then
    raise exception 'not_found'
      using hint = 'Loan request not found.';
  end if;

  if v_current.borrower_id != v_uid then
    raise exception 'forbidden'
      using hint = 'Only the borrower may modify this request.';
  end if;

  -- Cancellation: only from open or lender_selected
  if p_cancel then
    if v_current.status not in ('open', 'lender_selected') then
      raise exception 'invalid_transition'
        using hint = format(
          'Cannot cancel a request with status ''%s''.', v_current.status);
    end if;
    update public.loan_requests
       set status = 'cancelled', updated_at = now()
     where id = p_request_id;
